/* Intermediate3 · ShopKaro private origins, cache variants and safe releases. */
(function(){
  const N=AG.aws.n,OPT='658327ea-f89d-4fab-a63d-7e88639e58f6',OFF='4135ea2d-6df8-44a3-9df3-4b5a84be39ad',FORWARD='b689b0a8-53d0-40ab-baf2-68738e2966ac',ID='ESHOP',BUCKET='shop-images',OAC='OAC000001';
  const control=()=>({Name:'shop-images-oac',Description:'ShopKaro S3 REST origin',OriginAccessControlOriginType:'s3',SigningBehavior:'always',SigningProtocol:'sigv4'});
  function config(){return {CallerReference:'shop-original',Comment:'ShopKaro catalog + API',Enabled:true,Origins:{Quantity:2,Items:[{Id:'images',DomainName:BUCKET+'.s3.ap-south-1.amazonaws.com',S3OriginConfig:{OriginAccessIdentity:''}},{Id:'api',DomainName:'api.shopkaro.in',CustomOriginConfig:{HTTPPort:80,HTTPSPort:443,OriginProtocolPolicy:'https-only',OriginSslProtocols:{Quantity:1,Items:['TLSv1.2']}}}]},DefaultCacheBehavior:{TargetOriginId:'images',ViewerProtocolPolicy:'redirect-to-https',CachePolicyId:OPT,Compress:true,TrustedKeyGroups:{Enabled:false,Quantity:0}},CacheBehaviors:{Quantity:1,Items:[{PathPattern:'/api/*',TargetOriginId:'api',ViewerProtocolPolicy:'https-only',CachePolicyId:OPT,AllowedMethods:{Quantity:7,Items:['GET','HEAD','OPTIONS','PUT','PATCH','POST','DELETE']},TrustedKeyGroups:{Enabled:false,Quantity:0}}]},Aliases:{Quantity:0},ViewerCertificate:{CloudFrontDefaultCertificate:true},PriceClass:'PriceClass_All'};}
  function fixed(){const c=config();c.Origins.Items[0].OriginAccessControlId=OAC;c.CacheBehaviors.Items[0].CachePolicyId=OFF;c.CacheBehaviors.Items[0].OriginRequestPolicyId=FORWARD;return c;}
  function policy(){return {Version:'2012-10-17',Statement:[{Effect:'Allow',Principal:{Service:'cloudfront.amazonaws.com'},Action:'s3:GetObject',Resource:'arn:aws:s3:::'+BUCKET+'/*',Condition:{StringEquals:{'AWS:SourceArn':'arn:aws:cloudfront::123456789012:distribution/'+ID}}}]};}
  function seed(){return {region:'ap-south-1',cloudfront:[{id:ID,domain:'dshop.cloudfront.net',enabled:true,status:'Deployed',etag:'E1',version:1,config:config(),edgeCache:[{path:'/img/kurta-red.jpg',version:'v1'}],invalidations:[]}],originAccessControls:[],buckets:[{name:BUCKET,public:false,encryption:true,bpa:{BlockPublicAcls:true,IgnorePublicAcls:true,BlockPublicPolicy:true,RestrictPublicBuckets:true},objects:[{key:'img/kurta-red.jpg',version:'v2',size:100000,cacheControl:'public,max-age=86400'}]}]};}
  const file=v=>({content:JSON.stringify(v,null,2)}),dist=s=>(s.account.cloudfront||[]).find(d=>d.id===ID),bucket=s=>(s.account.buckets||[]).find(b=>b.name===BUCKET);
  function preserved(s){const d=dist(s),b=bucket(s);return !!d&&d.domain==='dshop.cloudfront.net'&&(s.account.cloudfront||[]).length===1&&!!b&&!b.public&&b.encryption&&Object.values(b.bpa||{}).length===4&&Object.values(b.bpa).every(x=>x===true)&&(b.objects||[]).some(o=>o.key==='img/kurta-red.jpg'&&o.version==='v2');}
  function deployed(s){const d=dist(s),c=d&&(d.deployedConfig||d.config),a=(s.account.originAccessControls||[]).find(a=>a.id===OAC);if(!c||!c.Origins||!c.DefaultCacheBehavior||!c.CacheBehaviors)return false;const api=(c.CacheBehaviors.Items||[])[0];return c.Enabled&&d.status==='Deployed'&&c.CallerReference==='shop-original'&&c.Origins.Quantity===2&&(c.Origins.Items||[]).some(o=>o.Id==='images'&&o.DomainName===BUCKET+'.s3.ap-south-1.amazonaws.com'&&o.OriginAccessControlId===OAC&&o.S3OriginConfig&&!o.S3OriginConfig.OriginAccessIdentity)&&(c.Origins.Items||[]).some(o=>o.Id==='api'&&o.DomainName==='api.shopkaro.in'&&o.CustomOriginConfig&&o.CustomOriginConfig.OriginProtocolPolicy==='https-only')&&c.DefaultCacheBehavior.TargetOriginId==='images'&&c.DefaultCacheBehavior.CachePolicyId===OPT&&['redirect-to-https','https-only'].includes(c.DefaultCacheBehavior.ViewerProtocolPolicy)&&c.DefaultCacheBehavior.TrustedKeyGroups&&!c.DefaultCacheBehavior.TrustedKeyGroups.Enabled&&c.DefaultCacheBehavior.TrustedKeyGroups.Quantity===0&&(!c.DefaultCacheBehavior.TrustedSigners||!c.DefaultCacheBehavior.TrustedSigners.Enabled)&&c.CacheBehaviors.Quantity===1&&!!api&&api.PathPattern==='/api/*'&&api.TargetOriginId==='api'&&['https-only','redirect-to-https'].includes(api.ViewerProtocolPolicy)&&api.CachePolicyId===OFF&&api.OriginRequestPolicyId===FORWARD&&api.AllowedMethods&&Array.isArray(api.AllowedMethods.Items)&&api.AllowedMethods.Items.includes('POST')&&!!a&&a.config.SigningBehavior==='always'&&a.config.SigningProtocol==='sigv4'&&a.config.OriginAccessControlOriginType==='s3'&&(s.account.originAccessControls||[]).length===1;}
  function scopeOK(s){const b=bucket(s),p=b&&b.policy,t=p&&p.Statement;return Array.isArray(t)&&t.length===1&&t[0].Effect==='Allow'&&t[0].Principal&&t[0].Principal.Service==='cloudfront.amazonaws.com'&&t[0].Action==='s3:GetObject'&&t[0].Resource==='arn:aws:s3:::'+BUCKET+'/*'&&t[0].Condition&&t[0].Condition.StringEquals&&(t[0].Condition.StringEquals['AWS:SourceArn']||t[0].Condition.StringEquals['aws:SourceArn'])==='arn:aws:cloudfront::123456789012:distribution/'+ID;}
  const fresh=s=>{const d=dist(s),r=AG.cdnResponse(s.account,d,'/img/kurta-red.jpg');return r.status===200&&r.version==='v2'&&!(d.edgeCache||[]).some(e=>e.path==='/img/kurta-red.jpg');};
  const SOLUTION=['aws cloudfront create-origin-access-control --origin-access-control-config file://oac.json','aws cloudfront update-distribution --id ESHOP --if-match E1 --distribution-config file://distribution-fixed.json','aws cloudfront wait distribution-deployed --id ESHOP','aws s3api put-bucket-policy --bucket shop-images --policy file://origin-policy.json',"aws cloudfront create-invalidation --distribution-id ESHOP --paths '/img/kurta-red.jpg'",'aws cloudfront wait invalidation-completed --distribution-id ESHOP --id I000001'];
  function plan(k){const req=k.requests*1e6,variants=[1,20,200][k.key],misses=k.days===0?req:Math.min(req,1000*20*variants*Math.ceil(30/k.days)),hit=1-misses/req,freshSeconds=k.versioned?300:k.days*86400,gross=req*0.0001*0.085+req/10000*0.01+misses/1000*0.0004;return {req,misses,hit,freshSeconds,gross,p50:hit>=0.5?25:200,ok:k.requests>=20&&hit>=0.90&&freshSeconds<=300};}
  function Q(q,correct,wrong,answer,explain,domain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain,domain};}
  AG.registerLevels('intermediate',[{
    id:'cloudfront',icon:'🌍',title:'CloudFront — private origin, cache key aur fresh release',badge:'Edge Engineer',
    hook:{when:'ShopKaro · image-heavy launch · fictional course story',title:'"Chennai mein image late, sale ke baad old price image!"',text:'Priya ke synthetic test mein Chennai/Guwahati product images 2–3 seconds leti hain; numbers course scenario hain, AWS promise nahi. Ravi ne CDN lagaya, par same image URL overwrite karne par old sale artwork dikh raha hai. Bucket private karte hi fresh requests 403 ho gayi. Cache speed, origin authorization aur content freshness ko separate fix chahiye.'},
    objectives:['<b>Trace</b>: edge hit/miss, regional cache aur origin load samjho','<b>Protect</b>: S3 REST origin + OAC + scoped SourceArn policy + BPA','<b>Cache safely</b>: key variants, TTL, API bypass and forwarding choose karo','<b>Release</b>: versioned paths vs invalidation; browser cache boundary pehchano','<b>Review</b>: HTTPS, signed viewer access, edge functions and pricing mode compare karo','<b>Repair</b>: config/ETag update, deployment and completed eviction ko state se verify karo'],
    steps:[
      {q:'CDN origin se har image baar-baar kyun nahi mangta?',analogy:'Jaipur warehouse se har packet bhejne ke bajay local kirana stock rakhta hai. Local stock hit ho toh nearby customer ko warehouse round trip bachti hai; new stock first time warehouse se aata hai.',body:'<pre>Viewer → CloudFront PoP\n  hit → cached response\n  miss → eligible regional edge cache\n       → origin fetch → cache → response</pre>',points:['AWS current overview lists 750+ Points of Presence. PoP/city/physical location count interchangeable nahi. Exact nearest-city or fixed20 ms guarantee nahi; routing and cache warmth affect latency.','Hit ratio = requests served from cache / cacheable requests. Miss, expiration, eviction, revalidation and uncacheable paths origin traffic affect karte hain; PoP cache permanent copy nahi.','Assumed example:20 million image requests/month,95% hits →1 million origin requests, not20 million. Viewer bytes still deliver hote hain; cache hits viewer egress free nahi banate.'],asli:'Action: dry run ka first fetch/miss aur second hit compare karo. Diagram timings illustrative hain; lab11 actual HTTP latency or hit ratio measure nahi karta.'},
      {q:'Distribution mein path, cache key aur forwarded data kaun decide karta hai?',analogy:'Delivery board ke route rules, stock label aur warehouse request note separate documents hain. Note mein har customer detail likhna stock label ka part banana zaroori nahi.',body:'<div class="tbl-wrap"><table><tr><th>Control</th><th>Job</th><th>Example</th></tr><tr><td>Origin</td><td>Content source</td><td>S3 REST, ALB, API/custom origin</td></tr><tr><td>Ordered cache behavior</td><td>First matching path rule and target</td><td>/api/* before default images</td></tr><tr><td>Cache policy</td><td>TTL bounds + key headers/cookies/query</td><td>Public assets reuse few variants</td></tr><tr><td>Origin request policy</td><td>Extra request values forwarded without keying</td><td>Needed API auth/cookies/query</td></tr><tr><td>Response headers policy</td><td>Response security/CORS headers</td><td>Not an origin permission grant</td></tr></table></div><p class="muted">Phone par table ki baaki columns ke liye table ko sideways swipe karo.</p>',points:['Key mein included values origin ko automatically forward hote hain. Origin request policy extra values send kar sakti hai without adding cache variants; response content vary kare toh missing key causes wrong/shared responses.','MinimumTTL>0 can cache even origin no-cache/no-store/private directives. Managed CachingOptimized minimum1 second, default 86400 seconds; authenticated API ke liye blind reuse unsafe hai.','Managed CachingDisabled has min/default/maxTTL0. CachingDisabled alone Authorization/cookies/query forwarding configure nahi karta. Reviewed origin request policy and origin Host/TLS contract bhi chahiye.'],asli:'Action: mission cat distribution-fixed.json run karo. Default images use CachingOptimized; ordered /api/* uses CachingDisabled and explicit forwarding policy. API origin TLS hostname contract assumed, not runtime-tested.'},
      {q:'S3 private rahe aur CloudFront read kare: three links kaunse?',analogy:'Warehouse gate public ke liye band hai. Signed delivery badge, approved delivery company aur exact branch permission tino match karne chahiye.',body:'<pre>S3 REST origin\n + attached OAC: always / sigv4 / s3\n + bucket Allow: cloudfront.amazonaws.com\n   Action s3:GetObject; exact object prefix\n   StringEquals AWS:SourceArn = distribution ARN\n + Block Public Access stays ON</pre>',points:['OAC object create karna attachment nahi. OriginAccessControlId distribution origin mein attach karo, current ETag se update karo, deployment finish hone do. OAI legacy hai; new S3 designs usually OAC prefer karte hain.','S3 website endpoint custom HTTP origin hai; OAC/OAI website endpoint support nahi karte. Private OAC design S3 REST origin use karta hai. New bucket ownership Bucket-owner-enforced default suitable hai.','SSE-KMS origin needs reviewed KMS key policy permission too. OAC or bucket policy alone KMS decrypt grant nahi. This fixture/lab uses SSE-S3 to keep one permission boundary.','Origin protection viewer entitlement nahi. Public viewers CDN image dekh sakte hain even private S3 origin; premium viewers ke liye signed URL/cookie or app authorization separately add karo.'],example:'<div class="war-story"><b>Galti jo sab karte hain:</b> CDN403 ko BPA off karke fix karna. Missing OAC link/SourceArn, wrong origin type, explicit Deny and KMS permission inspect karo; public bucket origin bypass khol sakta hai.</div>',asli:'Action: triage record mein old OAI principal compare karo. CloudFront service Principal + current SourceArn correct association needed; BPA valid scoped OAC access ko blanket block nahi karta.'},
      {q:'Har header/cookie/query cache key mein add karne se kya tootega?',analogy:'Same red kurta ke stock labels har tracking ID ke liye alag karoge toh shared shelf reuse gir jayega. Par size/color actual item badle toh label se size/color hatana wrong item bhejega.',body:'<div class="tbl-wrap"><table><tr><th>Input</th><th>Key decision</th><th>Failure</th></tr><tr><td>utm tracking only</td><td>Exclude if response identical</td><td>Unnecessary variants, low hit ratio</td></tr><tr><td>Image width/format changes bytes</td><td>Include normalized meaningful variant</td><td>Wrong-size/format image if omitted</td></tr><tr><td>User auth/session response</td><td>Disable shared cache or reviewed secure design</td><td>Cross-user data leak</td></tr></table></div><p class="muted">Phone par table ki baaki columns ke liye table ko sideways swipe karo.</p>',points:['Smallest correct key choose karo, smallest possible key blindly nahi. Origin response semantics and confidentiality first; hit ratio second.','Company-scale hypothetical:1,000 assets ×20 active caches ×20 irrelevant variants =400,000 possible first-fill objects. Real skew/collapse/eviction differs; count is intuition, not AWS benchmark.','All headers policy cost/hit problem ke alawa secret-bearing data forwarding bhi badha sakti hai. Required inputs audit karo; cacheable personal content ko one public key par collapse mat karo.'],asli:'Action: flowlab key None → +query → high-cardinality header/cookie mode change karo. Toy miss count grows; goal must preserve fixed demand and safe freshness.'},
      {q:'Old price artwork change kaise publish karo: TTL, invalidation ya new path?',analogy:'Old catalog page se same shelf label read hota rahega. New labeled edition publish karke catalog pointer update karna repeat shelf clearing se easier rollback deta hai.',body:'<div class="tbl-wrap"><table><tr><th>Choice</th><th>Kab use karein</th><th>Boundary</th></tr><tr><td>Versioned filename</td><td>Routine releases; img/kurta.v2.jpg</td><td>HTML/manifest pointer promptly update; browser pointer cache matters</td></tr><tr><td>Invalidation</td><td>Same URL emergency correction</td><td>Wait Completed; no browser/corporate cache flush</td></tr><tr><td>Short TTL</td><td>Frequently updated shared content</td><td>More origin requests; not instant invalidation</td></tr></table></div><p class="muted">Phone par table ki baaki columns ke liye table ko sideways swipe karo.</p>',points:['Pay-as-you-go first 1,000 invalidation paths/tags/month no added charge; beyond approx $0.005/path/tag (₹0.44 at ₹88/$1). Wildcard /* counts as one path but broad refill increases origin load.','S3 VersionId alone public URL change nahi karta. Versioned filename/path or correctly keyed version query is a different URL; do not confuse bucket versioning with CDN release naming.','CloudFront invalidation can remove edge old bytes, yet browser old max-age still serve kar sakta hai. New path + short-lived HTML/manifest/client refresh contract required.'],example:'<div class="war-story"><b>Production me kya hota hai:</b> Deploy new asset, but old HTML cached1 day points old asset. Asset versioning correct hone ke bawajood release visible nahi. Pointer caching and rollback order test karo.</div>',asli:'Action: main mission same-path emergency fix uses targeted invalidation and completion waiter. Planner routine-release example long assets + versioned paths +300 second pointer freshness assumption use karta hai.'},
      {q:'HTTPS aur viewer access ko OAC se alag kyun rakhein?',analogy:'Delivery van ka badge warehouse access deta hai; customer ka paid membership delivery entitlement deta hai. Road encryption neither membership nor warehouse policy replace karta hai.',body:'<div class="tbl-wrap"><table><tr><th>Requirement</th><th>Choice</th><th>Limit</th></tr><tr><td>Viewer custom HTTPS name</td><td>Alternate domain + matching ACM cert in us-east-1</td><td>Origin certificate regional/hostname contract separate</td></tr><tr><td>One premium file</td><td>App signs CloudFront URL after entitlement check</td><td>Expiry/policy/key rotation; bearer link can leak</td></tr><tr><td>Many restricted files</td><td>Signed cookies, trusted key groups</td><td>Cookie scope/client support and entitlement still matter</td></tr><tr><td>Direct S3 temporary operation</td><td>S3 presigned URL</td><td>Direct S3, no CloudFront edge authorization</td></tr></table></div><p class="muted">Phone par table ki baaki columns ke liye table ko sideways swipe karo.</p>',points:['App private key signs viewer URL/cookie; CloudFront validates with trusted public key group. CloudFront does not autonomously decide paid membership or generate app entitlement.','Shield Standard DDoS protection automatic at no extra charge; WAF web rules add application filtering, pricing depends plan. Geo restriction approximate country access policy, not full compliance/data-residency enforcement.','Default *.cloudfront.net certificate needs no custom ACM request. Custom viewer ACM certificate us-east-1 rule does not force S3/ALB origin into us-east-1.'],asli:'Interview follow-up: private S3 + OAC alone premium file ko paid-only banata hai? Nahi. Viewer entitlement/control aur origin bypass protection dono boundaries design karo.'},
      {q:'Dynamic API, private ALB aur edge code ke liye CloudFront fit hai?',analogy:'Nearby delivery desk sirf stocked parcels nahi, fresh custom orders ka encrypted connection bhi handle karta hai. Tiny label rewrite aur warehouse-dependent computation alag machinery chahiye.',body:'<div class="tbl-wrap"><table><tr><th>Choice</th><th>Kab</th><th>Boundary</th></tr><tr><td>CloudFront /api/*</td><td>HTTP API edge TLS, WAF; reviewed no-cache/forwarding</td><td>POST/auth still origin/app tested; dynamic content can benefit without caching</td></tr><tr><td>CloudFront Functions</td><td>Small viewer request/response JS rewrites</td><td>10 KB code,2 MB memory; no general network/body access; runtime2.0 KVS available</td></tr><tr><td>Lambda@Edge</td><td>Heavier viewer/origin logic, network/body needs</td><td>Different runtime/quotas/cost; verify event restrictions</td></tr><tr><td>VPC origin</td><td>Supported private ALB/NLB/EC2 origin</td><td>Supported region/features, ENI/SG/deployment requirements verify</td></tr></table></div><p class="muted">Phone par table ki baaki columns ke liye table ko sideways swipe karo.</p>',points:['CloudFront supports private VPC origins now; blanket public-ALB-only claim outdated hai. This level labs S3 metadata only; VPC-origin network runtime untested.','Non-HTTP TCP/UDP with static global entry/failover points toward Global Accelerator. CloudFront also has optional Anycast Static IP lists for HTTP workloads now; ordinary distribution DNS and advanced paid IP feature ko distinguish karo.','Origin request policy forwarding viewer Host can mismatch origin TLS/app routing. Current API fixture uses AllViewerExceptHostHeader after assumed api.shopkaro.in contract review; intended managed use cases include API Gateway/Lambda URLs. Production ALB header/authorization needs independently verify.'],asli:'Action: cat distribution-fixed.json mein /api/* target api + CachingDisabled dekho. Correct API forwarding metadata does not prove actual auth/session response correctness.'},
      {q:'Hit ratio high ho toh viewer bandwidth bill bhi near-zero hota hai?',analogy:'Warehouse trips kam hue, par local delivery van customers tak same number of parcels le jaati hai. Warehouse load saving aur viewer delivery cost alag meters hain.',body:'<p>Pay-as-you-go: US/commercial first-tier example approx $0.085/GB viewer DTO and$0.010/10,000 HTTPS requests. Geography/tier changes rates. Monthly allowance includes 1TB viewer DTO and10 million HTTP(S) requests across eligible billing scope; AWS origin→CloudFront fetch transfer free, S3 GET/storage/KMS still charged.</p>',points:['Current flat-rate plans also exist: per-distribution bundled monthly plans including selected WAF/DNS/compute/storage features. Pay-as-you-go toy math ko flat-rate invoice mat bolo; plan allowance/features/current terms verify karo.','Ordinary pay-as-you-go disabled distribution ka invented $50/month edge-reservation fee nahi. Actual requests/transfer stop, related storage, subscriptions, dedicated features or pricing plan costs can remain.','Price classes exclude some costlier edge regions and trade latency/coverage for cost; origin remains independent. No universal Class100=all cheapest users or fixed nearest-city latency guarantee.','Flowlab displays gross usage subtotal before free allowances/discounts/plans:100 KB per response, US first-tier rates +S3 GET approx $0.0004/1,000. ₹88=$1. WAF/logging/edge compute/other storage/taxes extra.'],asli:'Action: increase cache hit ratio; modeled origin GETs drop, viewer bytes and CDN delivery charges remain. Card numbers are verified approximate list rates, planner workloads/latency are explicit teaching assumptions.'},
    ],
    myth:[{myth:'CDN always20 ms aur viewer egress10× cheaper guaranteed hai.',sach:'PoP selection, network and hit ratio vary. Origin load can drop; viewer bytes still delivered and charged per selected plan/rate.'},{myth:'OAC create kar diya: private bucket and paid viewer authorization done.',sach:'Attach OAC, scoped bucket/KMS permissions and deployment needed. Signed viewer access/entitlement separate boundary hai.'},{myth:'All headers in key safest; minimum TTL with no-store means no cache.',sach:'Relevant response variants key mein chahiye; irrelevant headers fragment cache. MinimumTTL>0 can override private/no-store; use reviewed CachingDisabled for sensitive APIs.'},{myth:'Invalidation clears browser caches; disabled ordinary CDN costs $50/month reservation.',sach:'Invalidation evicts CloudFront copies, not browser/corporate caches. No invented ordinary base reservation fee; related resources/features/plans may still cost.'}],
    playbook:{title:'Kab use karein / kab nahi — cache and release decision',use:['Global HTTP static/media with repeated content','HTTP APIs needing edge TLS/WAF and reviewed forwarding, even uncached','Private S3 origin with OAC and precise origin policy; viewer entitlement separately'],avoid:['Caching user-specific data under a shared public key','Treating a CDN as TCP/UDP transport or database replication','OAC on S3 website endpoint; bulk public access as403 workaround'],how:['Name resource and sensitivity; inspect origin type and app response variation','Choose ordered path behavior, minimal correct key, TTL and forwarding','Attach OAC + exact distribution SourceArn policy; keep BPA; check KMS if applicable','Use versioned assets + prompt manifest for routine releases; targeted completed invalidation for same-path emergency','Read config/ETag, merge update, wait deployed; inspect actual clients when authorized'],redflags:['Old OAI Principal; wrong SourceArn; created-but-unattached OAC','API inherits CachingOptimized; auth cookie omitted from safe design','New image uploaded but old HTML pointer cached; InProgress invalidation counted done','Cache hit ratio presented as measured latency or whole-app authorization proof'],rule:'Decision tree: HTTP? CloudFront candidate; personal response? disable shared cache/review auth. S3 REST private? OAC+scoped policy. Routine change? versioned path+short pointer. Emergency same URL? invalidate+wait, browser cache still matters. Tiny viewer rewrite? Functions; network/body/origin logic? evaluate Lambda@Edge.'},
    exam:[{cue:'"global repeated static content"',pick:'CloudFront',why:'Edge cache reduces eligible origin fetches; latency/cost depend workload.'},{cue:'"private S3 accessible via distribution only"',pick:'REST origin + OAC + SourceArn policy + BPA',why:'Viewer signed URL alone cannot protect public origin bypass.'},{cue:'"one paid download" / "many protected files"',pick:'Signed URL / signed cookies with trusted key groups',why:'App entitlement first; viewer permission separate from OAC.'},{cue:'"/api vs /img"',pick:'Ordered behaviors, CachingDisabled for selected API',why:'Forward needed auth/query/cookies and verify Host contract.'},{cue:'"custom CloudFront viewer ACM cert"',pick:'us-east-1',why:'Origin region/certificate choice separate.'},{cue:'"same URL stale after overwrite"',pick:'Targeted invalidation + completion; prefer versioned releases',why:'CloudFront completion does not purge browser cache.'},{cue:'"lightweight viewer header/URL rewrite"',pick:'CloudFront Functions',why:'Small JS viewer code; no general network or request-body access.'},{cue:'"block countries or web exploits"',pick:'Geo restriction / WAF per requirement',why:'Shield Standard DDoS protection different; not legal residency guarantee.'},{cue:'"private ALB behind CloudFront"',pick:'Review supported VPC origin',why:'Current feature exists; static-IP/non-HTTP constraints require precise service selection.'}],
    stages:[
      {type:'dryrun',title:'🔍 One image: miss, hit, stale aur safe release',goal:'Agla step par one cache transition dekho. Origin authorization aur browser freshness ke two decisions answer karo.',nodes:[N('user',150,80,{label:'Chennai'}),N('cf',440,80,{label:'CloudFront PoP'}),N('cf#regional',800,80,{label:'Regional cache'}),N('iam',800,265,{label:'OAC / sigv4'}),N('s3',800,445,{label:'S3 REST / v2'}),N('cf#cache',440,445,{label:'Edge copy / v1'}),N('dev',150,445,{label:'Release pointer'})],edges:[{from:'user',to:'cf'},{from:'cf',to:'cf#regional'},{from:'cf#regional',to:'iam'},{from:'iam',to:'s3'},{from:'cf',to:'cf#cache'},{from:'dev',to:'user'}],panels:[{id:'fetch',title:'Source / permissions'},{id:'fresh',title:'Version / cache boundary'}],steps:[
        {clock:'miss',say:'Viewer /img/kurta-red.jpg mangta hai. Eligible edge/regional caches miss hain. Origin request attached OAC sigv4 sign karta hai; bucket policy distribution SourceArn allow karti hai. Diagram config assumes correct OAC; no actual network latency measured.',flows:[{from:'user',to:'cf',tone:'ok'},{from:'cf',to:'cf#regional',tone:'slow'},{from:'cf#regional',to:'iam',tone:'ok'},{from:'iam',to:'s3',tone:'ok'}],panels:{fetch:['REST origin + attached signing OAC + scoped policy','BPA stays ON'],fresh:['Assume public asset response TTL 86400 seconds']}},
        {clock:'hit',say:'Next viewer same key request karta hai. Edge v1 copy fresh hai; origin fetch avoid hota hai. Viewer bytes still transfer hote hain; hit means no fresh origin authorization evaluation for already cached copy.',flows:[{from:'cf',to:'cf#cache',label:'same key',tone:'ok'}],panels:{fetch:['Cache hit avoids eligible origin request'],fresh:['Key differences may create separate variants']},ask:{q:'Fresh miss403, bucket private, OAC exists but origin has no OAC ID. Correct repair?',choices:['Attach OAC and scoped bucket policy, deploy; keep Block Public Access enabled','Disable BlockPublicPolicy and make every object public to hide the origin error','Add a CloudFront viewer signed URL while leaving OAC unlinked from S3 origin','Lower image TTL alone because expiration grants CloudFront service read permission'],answer:0,explain:'OAC attachment and authorization repair missing origin access. Public workaround opens bypass; viewer signature and TTL do not grant S3 origin permission.'}},
        {clock:'overwrite',say:'Ravi same S3 key par artwork v2 upload karta hai. Edge v1 copy still TTL ke andar fresh hai. S3 newest object aur current CloudFront response version alag ho sakte hain.',panels:{fresh:['Origin version=v2; cached response=v1','S3 versioning alone does not create a new CDN URL']}},
        {clock:'emergency',say:'Targeted invalidation create hui, status InProgress. Submission ko completed eviction mat gino. Completion ke baad next miss authorized origin se v2 fetch karegi.',nodes:{'cf#cache':{tone:'warn',badge:'v1 until complete'}},panels:{fetch:['New config deployment and invalidation are separate states'],fresh:['InProgress ≠ Completed']}},
        {clock:'routine release',say:'Future release /img/kurta.v3.jpg publish karo; HTML/manifest pointer update karo. Old HTML pointer cache lifetime bound kiye bina asset versioning alone5minute freshness guarantee nahi.',flows:[{from:'dev',to:'user',label:'new path pointer',tone:'ok'}],ask:{q:'Versioned assets ke baad old price image still1 day. Strong follow-up?',choices:['Inspect old HTML/manifest or app pointer cache; update pointer and freshness contract','Delete the S3 bucket because versioned filenames require a public website endpoint','Increase irrelevant cookie/header cache variants until old browser pointer disappears','Create OAC again because origin signing automatically forces every browser to refresh'],answer:0,explain:'Old pointer still references old asset. Bucket deletion, irrelevant key variants and duplicate OAC cannot clear browser HTML; short pointer cache/client refresh needed.'},panels:{fresh:['Versioned path bypasses old asset URL caches','Browser/corporate caches are not invalidated by CloudFront']}},
        {clock:'review',say:'Three checks: who may fetch origin, which response variant key identifies, and when clients learn new URL. DNS/ETag/Deployed metadata is not measured HTTP recovery.',panels:{fetch:['OAC origin permission ≠ viewer entitlement'],fresh:['Measure real client response version and headers separately']}},
      ],lesson:'Same-path overwrite can leave old cached bytes. Correct origin permission, cache variation and release pointer freshness are independent decisions.'},
      {type:'flowlab',title:'🎛️ Cache reuse vs five-minute release',goal:'Fixed demand at least 20 million requests/month, hit ratio ≥90%, modeled change visibility ≤300 seconds. Choose TTL, variant inputs and versioned release/pointer contract.',scenario:'Toy workload:1,000 public assets ×20 active caches; irrelevant query variants 20, high-cardinality headers/cookies 200. Uniform 30 day window; misses=first fills per variant/TTL cycle, capped at demand. Hit latency 25 ms, miss 200 ms two-point toy distribution; p50 not real measurement. Versioned path + release/pointer refresh assumed 300 seconds. 100 KB/response; gross US first-tier CDN DTO$0.085/GB + HTTPS$0.010/10,000 + S3 GET$0.0004/1,000; free allowances, plans, other fees excluded; ₹88/$1.',knobs:[{id:'days',label:'Public asset TTL',min:0,max:7,step:1,value:0,unit:' days'},{id:'key',label:'Key variant inputs',min:0,max:2,step:1,value:2,labels:{0:'Only needed path',1:'+ tracking queries',2:'+ varied headers'}},{id:'requests',label:'Monthly demand',min:10,max:50,step:10,value:20,unit:' M/month'},{id:'versioned',label:'Versioned release',min:0,max:1,step:1,value:0,labels:{0:'Off',1:'On / 300s contract'}}],model:k=>{const b=plan(k);return {readouts:[{label:'Modeled hit ratio',value:(b.hit*100).toFixed(1)+'%',tone:b.hit>=0.90?'ok':'bad'},{label:'Modeled origin requests',value:b.misses.toLocaleString()+'/month',tone:'info'},{label:'Toy p50 latency',value:b.p50+' ms',tone:'info'},{label:'Modeled visibility',value:b.freshSeconds+' seconds',tone:b.freshSeconds<=300?'ok':'bad'},{label:'Approx gross usage subtotal',value:'$'+b.gross.toFixed(2)+'/month · ₹'+Math.round(b.gross*88),tone:'info'}],verdict:{ok:b.ok,text:b.ok?'Toy budget passes. Real cache headers, browser pointers, authorization and geography-based invoice need independent tests.':'Example: TTL 1 day, path-only key, 20 million requests, versioned path On →97% hits, 300 seconds visibility; sensitive API caching stays disabled separately.'}};},check:k=>plan(k).ok,lesson:'At 20 million requests, 1 day TTL and path-only key: 600,000 origin requests,97% modeled hits. Versioned path + prompt pointer assumed 300 seconds. Viewer 2,000 GB and 20 million HTTPS requests still deliver; gross approx $190.24/month before free allowances/discounts/plans.'},
      {type:'bins',title:'🗂️ Content sensitivity → cache strategy',instructions:'Response freshness and confidentiality choose karo; origin/public/private labels alone TTL decide nahi karte.',bins:[{id:'long',label:'Cache long'},{id:'short',label:'Cache short'},{id:'off',label:'No shared cache'}],items:[{text:'Hashed app.8f3.js public immutable release asset',bin:'long',explain:'Long lifetime + new filename on release; HTML pointer short/fresh.'},{text:'Versioned public product photo path',bin:'long',explain:'Stable bytes per URL; safe public reuse.'},{text:'Public catalog HTML pointing to current release',bin:'short',explain:'Short pointer freshness protects release visibility; exact TTL from requirement.'},{text:'Public stock summary refreshed every30 seconds',bin:'short',explain:'Only if bounded staleness acceptable; authoritative checkout validates stock.'},{text:'Authenticated account balance response',bin:'off',explain:'Reviewed no shared cache avoids cross-user exposure; forward auth correctly.'},{text:'Checkout POST and user session response',bin:'off',explain:'No shared object caching; app authorization/idempotency still required.'}]},
      {type:'match',title:'🔑 Permission tool → exact boundary',instructions:'Origin access, CDN viewer access aur direct S3 access ko mix mat karo.',pairs:[{left:'App-approved one premium file through CDN',right:'CloudFront signed URL',explain:'App signs with trusted key; CloudFront validates viewer policy.'},{left:'App-approved many protected CDN files',right:'CloudFront signed cookies',explain:'Policy/cookie scope plus trusted key group; no origin permission by itself.'},{left:'Temporary direct S3 object operation',right:'S3 presigned URL',explain:'Direct S3 request; no CloudFront cache/viewer policy involved.'},{left:'CloudFront service authenticates to private S3 REST origin',right:'OAC + scoped bucket policy',explain:'Attached signing OAC and exact SourceArn; viewer may still be public.'}]},
      {type:'triage',title:'🩺 Private bucket ke baad CDN403',symptom:'Fresh /img/new.jpg request403. Distribution OAC attached, Deployed, SSE-S3 object exists. Bucket policy still old OAI principal allow karti hai. Evidence fixtures; no Moto HTTP request measured.',commands:[{cmd:'aws cloudfront get-distribution-config --id ESHOP',out:'{"ETag":"E2","DistributionConfig":{"Origins":{"Items":[{"Id":"images","DomainName":"shop-images.s3.ap-south-1.amazonaws.com","OriginAccessControlId":"OAC000001","S3OriginConfig":{"OriginAccessIdentity":""}}]}}}',clue:true,note:'Attached OAC; old OAI not used by origin.'},{cmd:'aws s3api get-bucket-policy --bucket shop-images',out:'{"Statement":[{"Effect":"Allow","Principal":{"AWS":"arn:aws:iam::cloudfront:user/CloudFront Origin Access Identity EOLD"},"Action":"s3:GetObject","Resource":"arn:aws:s3:::shop-images/*"}]}',clue:true,note:'Old OAI principal does not allow CloudFront service OAC requests with current SourceArn.'},{cmd:'aws s3api get-public-access-block --bucket shop-images',out:'{"PublicAccessBlockConfiguration":{"BlockPublicAcls":true,"IgnorePublicAcls":true,"BlockPublicPolicy":true,"RestrictPublicBuckets":true}}',clue:false,note:'BPA should stay enabled; valid scoped service principal policy is not a public workaround.'},{cmd:'aws cloudfront get-distribution --id ESHOP',out:'{"Distribution":{"Status":"Deployed","DistributionConfig":{"Enabled":true,"ViewerCertificate":{"CloudFrontDefaultCertificate":true}}}}',clue:false,note:'Default viewer TLS works in scenario; origin permission missing, not custom cert issue.'}],questions:[Q('Strongest cause of fresh object403?','Bucket allow names old OAI principal while origin now sends OAC service requests',['All four BlockPublicAccess flags reject every CloudFront service principal policy','Default CloudFront certificate must be replaced by an origin-region ACM certificate','Cache TTL 1 day grants anonymous writes but prevents signed S3 read requests'],0,'Old OAI policy does not grant current OAC service access. Scoped OAC works with BPA; viewer cert independent; TTL grants no S3 permissions.','secure'),Q('Repair preserving private origin?','Allow service GetObject on object prefix with current distribution SourceArn',['Make bucket public and remove SourceArn because OAC cannot use private S3','Attach an EC2 instance profile to CloudFront viewers to reuse temporary IAM keys','Change /img key to every Authorization header so policy principal updates itself'],1,'Scoped service Allow repairs OAC origin permission; BPA stays. Public bucket opens bypass; viewers do not attach EC2 roles; cache key does not edit IAM policy.','secure')]},
      (function(){const tasks=[{text:'Original distribution deployed/enabled, signing S3 OAC attached, /api/* no-cache with reviewed forwarding',check:deployed},{text:'Exact distribution-scoped service GetObject bucket allow, no public access',check:scopeOK},{text:'Fresh fixture fetch returns origin v2; old same-path edge entry evicted only after completion',check:fresh},{text:'Original distribution/origins/object/BPA preserved; no extra OACs',check:preserved}];return {type:'terminal',title:'🖥️ Mission — private origin and same-path emergency refresh',instructions:'First inspect: aws cloudfront get-distribution-config --id ESHOP. Read ETag E1 and cat distribution-fixed.json; JSON is the full merged config, not a patch. ls/cat three mission files inspect karo. Six intended state actions; OAC000001 and I000001 deterministic hain.',goal:'Keep ESHOP/dshop.cloudfront.net enabled. Attach always/sigv4 S3 OAC, use corrected full config with /api/* CachingDisabled + forwarding, wait deployed, allow exact ESHOP SourceArn GetObject with BPA ON. Origin img/kurta-red.jpg=v2 but edge fixture=v1; targeted invalidation must complete. Deleting bucket/distribution, public workaround, wrong policy or pending-only edits cannot win. Fixture returns modeled status/version, not real HTTP.',account:seed(),files:{'oac.json':file(control()),'distribution-fixed.json':file(fixed()),'origin-policy.json':file(policy())},tasks,success:AG.allOf(tasks),solution:SOLUTION.slice(),hints:SOLUTION.map((c,i)=>c+[' — nudge: signing identity first; attachment remains separate',' — get config/ETag first; E1 only valid until first update',' — stronger: desired config InProgress is not deployed serving state',' — exact SourceArn and service Principal; origin privacy remains ON',' — same URL emergency correction; submission is InProgress',' — final eviction completion; serving fixture now reads v2'][i]),successText:'Private origin config, scoped permission, API cache bypass and completed targeted eviction agree. Fixture status 200 / version v2 is derived from saved state, not measured AWS HTTP. Real auth, KMS/TLS, browser caches and app latency need separate runtime tests.'};})(),
      {type:'docker',title:'🐳 Lab11 — real CLI, explicit emulator gaps',project:'11-cloudfront-oac',goal:'README ex1–ex5: inspect JSON/ETag → create OAC/update request → scoped policy/BPA → invalidation metadata → cleanup. OAC link readback null means unverified, not passed private delivery.',why:'Actual CLI field syntax and metadata gaps debug karna seekho; Moto acceptance cannot certify real OAC auth or ETag concurrency.',steps:[{text:'README Setup isolation exports, then create lab bucket/object/distribution.',cmd:'cd aws-gurukul/docker-labs\n./start-moto.sh\nsource env.sh\ncd 11-cloudfront-oac\n# README Setup exports run karo.\nbash setup.sh\nsource .lab/resources.sh',expect:'Enabled=true; generated S3 REST origin and returned ETag.'},{text:'Create OAC, read ETag, submit update and scoped bucket policy. Inspect null OAC readback honestly.',cmd:'bash exercises.sh\nsource .lab/resources.sh',expect:'Status=Deployed but OAC=null in current Moto; BPA alltrue; policy stores exact distribution SourceArn.'},{text:'Inspect metadata only. Avoid invalidation-completed waiter on current Moto uppercase status.',cmd:'aws cloudfront get-invalidation --distribution-id "$DIST" --id "$INVALIDATION"',expect:'Status="COMPLETED" in Moto; AWS standard status is Completed. No actual edge eviction measured.'},{text:'Disable using config/current ETag, wait deployed, delete only saved resources.',cmd:'bash cleanup.sh',expect:'false then0/0/0 matching distribution/OAC/bucket counts.'}],observe:Q('Moto accepts STALE ETag and reads OAC=null. What result can be claimed?','CLI requests and scoped policy persisted; attachment/concurrency enforcement unverified',['Complete private CDN authorization and correct real-world concurrent-update protection','Fresh CDN image bytes measured across750 PoPs within a guaranteed300 second window','The AWS OAC field is invalid because current emulator silently discards the field'],2,'Emulator gaps limit evidence. No actual CDN/probes/concurrency proof; correct AWS fields can be dropped by an incomplete emulator.','secure')},
      {type:'quiz',title:'📝 Bonus — CDN trade-offs without slogans',questions:[
        Q('Private S3 REST origin, OAC object exists, fresh fetch 403. First config evidence?','OriginAccessControlId attachment, scoped bucket SourceArn policy and deployment',['Viewer signed URL length and CloudFront invalidation quota only, ignoring origin config','EC2 public IP assignment because every private S3 REST origin requires NAT ingress','Disabling all public-access controls before checking the bucket policy or OAC link'],0,'Attachment/policy/deployment govern origin access; SSE-KMS may add key permission. Viewer token/quota unrelated; EC2 public IP not needed; public workaround compromises origin boundary.','secure'),
        Q('Small public assets include random tracking query in cache key. Likely effect?','More variants reduce shared reuse even when underlying response bytes are identical',['Automatic improvement in hit ratio because every distinct tracking key shares one entry','Removal of all origin GET costs because query strings are never forwarded to an origin','Guaranteed per-user authorization because random tracking input acts as a signed token'],1,'Unneeded variants fragment cache; keys are not shared across values. Key inputs are forwarded; tracking randomness is not authorization and does not remove GET charges.','high-performing'),
        Q('New hashed asset path deployed but old release visible. Investigate?','HTML/manifest pointer caching and client refresh, then actual requested asset URL',['S3 VersionId because changing internal version guarantees all CDN URLs already changed','OAC SigningProtocol because sigv4 always forces browser manifest caches to refresh','PriceClass because selecting all regions overrides browser cache-control on pointers'],2,'Pointer can still reference old asset. S3 version differs from URL naming; OAC signs origin requests; price class does not purge browser caches.','high-performing'),
        Q('Premium course has hundreds of protected segments per viewer. Suitable viewer control?','App-authorized signed cookies with trusted key group and private origin protection',['Only OAC creation without viewer policy because origin privacy proves user membership','Public S3 website and one shared permanent password embedded in every segment URL','S3 presigned URL without CDN behavior while promising the same CDN edge authorization'],3,'Signed cookies can cover multiple protected files; app entitlement and origin privacy still required. OAC only origin-side; public password weak; direct S3 signature is a different access path.','secure'),
        Q('Viewer custom domain uses ACM. Where request the viewer certificate?','us-east-1 with matching alternate domain; origin certificate contract is separate',['Only the S3 bucket region because CDN always runs entirely inside the origin region','Any region because CloudFront automatically copies every ACM private key across regions','Only viewer country region because DNS source geography selects certificate ownership'],0,'CloudFront viewer ACM certificate must be us-east-1. Origin cert may be elsewhere; no general ACM automatic copy; viewer country does not define certificate region.','secure'),
        Q('Authenticated API inherits CachingOptimized with origin no-store. Safer reviewed behavior?','CachingDisabled plus required auth/query/cookie forwarding and correct origin Host contract',['Keep minimum TTL1 second and assume no-store always prevents any shared cache entry','Remove Authorization forwarding and cache under one key so private responses are faster','Use a new OAC with SigningBehavior never because OAC is the API cache policy setting'],1,'MinimumTTL can override no-store. Disabled cache and correct forwarding needed; stripping auth/shared key risky; OAC signing is not cache policy.','secure'),
        Q('Cheap viewer URL rewrite with no network/body needs. Candidate?','CloudFront Functions; verify runtime/code limits and viewer-event behavior',['Lambda@Edge is mandatory because CloudFront Functions cannot change request URIs','Regional RDS trigger because each CDN URI rewrite needs a SQL transaction first','Route53 weighted routing because DNS inspects HTTP paths and request headers'],2,'Functions fits lightweight viewer rewrites. Lambda@Edge can do more but not mandatory; RDS unrelated; DNS does not inspect HTTP path/header.','high-performing'),
        Q('Emergency invalidation is Completed. Some browsers still show old same-URL image. Why?','Browser/corporate cache is separate; versioned paths and pointer refresh can avoid old URL',['CloudFront completion guarantees all caches cleared so browser must be showing a new IP','OAC automatically pins browsers to old bytes until the service principal is made public','Invalidation can remove cached HTML only, while images can never be invalidated by path'],3,'CloudFront eviction does not purge downstream caches. Completion is not global browser control; OAC not browser byte pinning; image paths can be invalidated.','resilient'),
      ]},
    ],
    interview:{title:'🎤 CDN incident and release review',instructions:'Cache semantics, permissions, concurrency and evidence limits explain karo; final task existing resources repair karti hai.',questions:[
      Q('Get config ETagE1, another update occurs, your E1 update rejected. Next action?','Re-read latest config/ETag, merge intended edits, retry without overwriting others',['Retry the old full config indefinitely because ETag is only a decorative response field','Use fake disable-distribution operation so CloudFront silently drops concurrency checks','Delete the private bucket so the distribution automatically chooses a newer ETag'],0,'ETag is optimistic concurrency. Re-read/merge prevents lost updates; retry stale, fake op and bucket deletion do not resolve config conflict safely.','resilient'),
      Q('API response depends on a header excluded from shared cache key. What can break?','One variant can be served to another viewer; key design or cache bypass must match semantics',['Each header value is automatically keyed even when cache policy explicitly excludes it','Origin request policy always encrypts response variants into separate public cache entries','Higher cache hit ratio proves authorization correctness even with missing response variants'],1,'Response variation must be keyed safely or shared caching disabled. Forwarding does not automatically key; policies do not magically encrypt variants; hit rate does not establish confidentiality.','secure'),
      Q('2,000 pay-as-you-go invalidation paths/month, first 1,000 free. Approx added charge?','Approx $5/month for1,000 extra paths; viewer and other feature costs remain separate',['Approx $10/month because the free monthly paths are charged retroactively at0.005 each','Approx $50/month flat reservation because the distribution remains deployed even disabled','Approx $0/month for any number of paths because an OAC makes invalidations unlimited'],2,'1,000×$0.005=$5. Free paths not retroactively charged; no invented base reservation; OAC does not change pay-as-you-go invalidation quota.','cost-optimized'),
      Q('Private ALB origin required. Current CloudFront design candidate?','Supported VPC origin with reviewed region, SG/ENI and feature restrictions',['Impossible because CloudFront categorically requires every origin to be public forever','S3 OAC principal attached directly to ALB replaces all network paths and TLS review','Public ALB with0.0.0.0/0 ingress automatically proves origin bypass is prevented'],3,'VPC origins support eligible private ALB/NLB/EC2. Blanket public-only is outdated; S3 OAC is not ALB routing; public ingress does not prove bypass restriction.','secure'),
      {terminal:(function(){const a=seed(),d=a.cloudfront[0];d.config=fixed();d.config.CacheBehaviors.Items[0].CachePolicyId=OPT;d.etag='E7';d.version=7;a.originAccessControls=[{id:OAC,etag:'O1',config:control()}];a.cdnOacCounter=1;a.buckets[0].policy=policy();const tasks=[{text:'Existing distribution deployed with /api/* CachingDisabled; S3/OAC preserved',check:deployed},{text:'Original scoped service policy/BPA/object retained',check:s=>scopeOK(s)&&preserved(s)},{text:'Completed targeted eviction; fresh v2 fixture',check:fresh}];const solution=['aws cloudfront update-distribution --id ESHOP --if-match E7 --distribution-config file://repair-config.json','aws cloudfront wait distribution-deployed --id ESHOP',"aws cloudfront create-invalidation --distribution-id ESHOP --paths '/img/kurta-red.jpg'",'aws cloudfront wait invalidation-completed --distribution-id ESHOP --id I000001'];return {title:'🖥️ Existing OAC works; repair API cache and stale asset',goal:'Current ETagE7. OAC and scoped policy already exist: recreate/public workaround nahi. cat repair-config.json read karo, current full-config update + deploy; same-path image v1 edge copy invalidate + complete. API metadata must use CachingDisabled and reviewed forwarding; real API auth not simulated.',account:a,files:{'repair-config.json':file(fixed())},tasks,success:AG.allOf(tasks),solution,hints:solution.slice(),successText:'Existing origin protection retained; deployed API no-cache metadata and completed stale-byte eviction agree. Runtime app authorization, Host/TLS and browser freshness still require real tests.'};})()},
    ]},
    success:['CDN hit, origin permission, cache variant aur client freshness separately explain kar sakta hoon','S3 REST OAC policy and viewer signed access boundaries choose kar sakta hoon','ETag conflict, deployment and completed invalidation state repair kar sakta hoon','Toy hit/latency/cost assumptions ko actual measured AWS behavior se distinguish kar sakta hoon'],
    homework:'<p><b>Optional approved real AWS sandbox only; billable:</b> pricing mode/geography/traffic estimate first. Private test S3 REST bucket with ownership/BPA, supported OAC always/sigv4 and scoped SourceArn policy configure karo. Origin and viewer permissions separately test: direct anonymous S3 denied, approved CDN read works, private viewer scenario has valid/expired signatures checked. Actual Cache-Control/Age/X-Cache and requested paths inspect karo; safe versioned asset + short manifest release observe karo. One same-path correction target invalidate karke Completed and actual browser cache behavior separately compare karo. Custom viewer cert us-east-1; API origin header/auth/TLS contract review. Cleanup: disable test distribution through latest full config/ETag, wait deployed, detach/remove OAC as appropriate and delete test distribution before bucket; remove OAC, test objects/versions/bucket, only test policy/certs/DNS/WAF/log/IP/plan resources review and clean. Existing/shared distributions, keys, policies and origin resources preserve karo.</p>',
    cards:[{front:'Cache policy vs origin request policy?',back:'Cache policy controls TTL/key. Key values also forward; origin request policy forwards extra inputs without keying. Response variation/auth must remain safe.'},{front:'Private S3 CDN read ke links?',back:'S3 REST origin + attached OAC always/sigv4 + scoped service GetObject/SourceArn policy + deployment. BPA stays ON; KMS objects may need key permission.'},{front:'OAC vs signed URL/cookie?',back:'OAC origin authentication. App-signed URL/cookie viewer entitlement via trusted key groups. Private origin alone does not make viewers paid-only.'},{front:'Versioned file vs invalidation?',back:'Routine new path + promptly refreshed HTML/manifest. Emergency same path invalidate and wait Completed. Browser/corporate caches are not purged by CloudFront.'},{front:'Cache API safely?',back:'Reviewed CachingDisabled for sensitive dynamic API plus needed auth/cookie/query forwarding and origin Host/TLS. MinimumTTL>0 can override no-store.'},{front:'CloudFront custom viewer certificate region?',back:'ACM us-east-1; match alternate domain. Origin region/certificate contract separate; default CloudFront hostname already has certificate.'},{front:'Stale ETag update?',back:'PreconditionFailed: re-read latest config/ETag, merge, retry. Update full DistributionConfig; wait deployment. Moto currently fails to enforce this precondition.'},{front:'High hit ratio means lower viewer bytes?',back:'No. Fewer eligible origin fetches; viewer bytes still delivered. Pricing mode/geography/allowances/features matter; no invented ordinary disabled-distribution base fee.'}],
  }]);
})();
